    4 0 0 -1 0 -> 0 1 1
    7 -1 -2 -3 -2 -5 -1 -2 -> -1 1 1
    6 -1 -2 -3 1 2 3 -> 6 4 6
    5 -3 -2 -1 -2 -3 -> -1 3 3
*/
